mapper.update:
update board
set subject=#{subject}, username=#{username}, contents=#{contents}, password=password(#{password}), modify_date=now() 
where idx=#{idx}

mapper.select:
SELECT idx, subject, username, viewcount, password, created_date, contents  
FROM board
WHERE idx = #{id}

SELECT if(password=password(#{password}),true,false) as result 
FROM board
WHERE idx=#{idx}
